"""Pipeline-era thesis and direct, scoped competitive positioning."""
def position(slides):
    slides[0]['title']='The pipeline<br>era is <em>over.</em>'
    slides[0]['notes']+=' Positioning statement and product thesis, not a prediction that all pipeline systems have disappeared. Oyzu eliminates customer-authored application pipelines and templates for supported workflows; it still generates an execution graph.'
    i=next(i for i,s in enumerate(slides) if s['label']=='THE BUYER’S ALTERNATIVES')
    slides[i]=dict(label='THE COMPETITIVE DIVIDE',title='Who owns the delivery logic?',subtitle='',theme='cp-compare',body='''<div class="cp-intro">Powerful orchestration still leaves a workflow to own.<br><b>Oyzu makes generating that workflow the product’s responsibility.</b></div><table class="cp-table"><thead><tr><th></th><th><span class="cp-brand"><img src="tool-logos/gitlab.svg" alt="">GitLab</span></th><th><span class="cp-brand"><img src="tool-logos/harness.svg" alt="">Harness</span></th><th><img class="cp-oyzu-brand" src="logo-color.svg" alt="Oyzu"><small>PROPOSED MODEL</small></th></tr></thead><tbody><tr><th>Core approach</th><td>Integrated DevSecOps with CI/CD pipelines</td><td>Broad delivery orchestration with pipelines</td><td>Intent + native project facts + policy → execution plan</td></tr><tr><th>Reuse & governance</th><td>Auto DevOps, shared configuration and pipeline execution policies</td><td>Reusable pipeline / stage / step templates and policy as code</td><td>Policy governs generation; no application pipeline templates</td></tr><tr><th>Customer owns</th><td>Pipeline configuration or adopted defaults; customization and exceptions</td><td>Pipeline design or adopted templates; integrations and exceptions</td><td>Application intent, organizational rules and explicit exceptions</td></tr><tr><th>Where each is strong</th><td>Integrated source-to-delivery lifecycle</td><td>Deep delivery capabilities and orchestration flexibility</td><td>Opinionated local-to-CI experience; product-owned workflow generation</td></tr></tbody></table><div class="cp-verdict"><b>The bet:</b> less customer-owned automation to build, roll out and maintain.</div>''',source='<a href="https://docs.gitlab.com/topics/autodevops/">GitLab Auto DevOps</a> · <a href="https://docs.gitlab.com/user/application_security/policies/pipeline_execution_policies/">Pipeline policies</a> · <a href="https://developer.harness.io/docs/platform/templates/template/">Harness templates</a> · <a href="https://developer.harness.io/docs/platform/governance/policy-as-code/harness-governance-overview/">Policy as code</a>. Documented models vs. Oyzu target; not a feature ranking.' ,notes='GitLab Auto DevOps can build/test/deploy without a customer-authored pipeline; customization uses templates. GitLab pipeline execution policies can centrally inject or override pipeline configuration. Harness templates support reuse at step, stage and pipeline scope; policy as code supplies governance. Do not assert every policy change requires editing every repository or that incumbents lack governance. Customer maintenance varies with adoption, defaults and scope. Oyzu retains native config, policies and bounded extensions; custom unsupported workflows can still require engineering. Advantage is a maintenance hypothesis to validate, not measured superiority. References: https://docs.gitlab.com/topics/autodevops/ ; https://docs.gitlab.com/user/application_security/policies/pipeline_execution_policies/ ; https://developer.harness.io/docs/platform/templates/template/ ; https://developer.harness.io/docs/platform/governance/policy-as-code/harness-governance-overview/')
    together=dict(label='COMPETE ON THE MODEL · INTEGRATE ON ADOPTION',title='Keep the investment.<br><em>Change the operating model.</em>',subtitle='',theme='cp-together',body='''<div class="cp-lanes"><div class="cp-top"><small>APPLICATION INTENT + ORGANIZATIONAL POLICY</small><img src="logo-color.svg" alt="Oyzu"><p>Generate the required work. Govern the tools. Connect the evidence.</p></div><div class="cp-down" aria-hidden="true"><svg viewBox="0 0 1200 45" preserveAspectRatio="none"><path d="M600 0V17H195V39M600 17V39M600 17H1005V39"/><path d="m189 33 6 6 6-6m393 0 6 6 6-6m393 0 6 6 6-6"/></svg></div><div class="cp-targets"><div><small>RUN WHERE TEAMS ALREADY WORK</small><h3>Existing CI</h3><div class="cp-logo-row"><span><img src="tool-logos/gitlab.svg" alt=""><b>GitLab</b></span><span><img src="tool-logos/githubactions.svg" alt=""><b>GitHub Actions</b></span><span><img src="tool-logos/jenkins.svg" alt=""><b>Jenkins</b></span><span><img src="tool-logos/harness.svg" alt=""><b>Harness</b></span></div></div><div><small>KEEP SPECIALIST CAPABILITIES</small><h3>Checks & artifacts</h3><div class="cp-logo-row"><span><img src="tool-logos/snyk.svg" alt=""><b>Snyk</b></span><span><img src="tool-logos/jfrog.svg" alt=""><b>JFrog</b></span><span><img src="tool-logos/sonatype.svg" alt=""><b>Sonatype</b></span><span><img src="tool-logos/docker.svg" alt=""><b>Docker</b></span></div></div><div><small>ADOPT DELIVERY PROGRESSIVELY</small><h3>Existing delivery</h3><div class="cp-logo-row"><span><img src="tool-logos/harness.svg" alt=""><b>Harness CD</b></span><span><img src="tool-logos/aws.svg" alt=""><b>AWS</b></span><span><img src="tool-logos/azure.svg" alt=""><b>Azure</b></span><span><img src="tool-logos/googlecloud.svg" alt=""><b>Google Cloud</b></span><span><img src="tool-logos/kubernetes.svg" alt=""><b>Kubernetes</b></span></div></div></div></div><div class="cp-strategy"><div><b>Direct competition</b><p>Who owns application delivery logic, governance and the associated platform budget.</p></div><div><b>Better together, early</b><p>Use existing execution and specialist delivery. Make Oyzu adoption possible without a wholesale migration.</p></div></div>''',source='Intended integration strategy, not a list of shipped integrations or commercial partnerships. Existing CI/CD may retain a bootstrap or handoff workflow.',notes='Oyzu generates a deterministic execution plan per run rather than asking customers to maintain application pipeline templates. Thin CI bootstraps and existing deployment workflows may remain during adoption. A proposed Harness CD handoff must bind artifact digest, evidence, authorization and observed result; exact adapter boundary requires implementation and validation. Do not promise no pipelines anywhere while using an incumbent for orchestration. Core distinction is who authors and maintains supported application delivery logic. Compete directly on governed delivery ownership while complementing source hosting, compute, registries, scanners and specialist delivery capabilities. Own compute/CD are future options, not mandatory migration.')
    slides.insert(i+1,together)
    return slides
